//! The C header: the contract every other binding is generated against.

use std::fmt::Write;

use crate::common::{DocStyle, block_comment, field_doc};
use crate::model::{Api, Role, TypeRef, screaming};

/// Renders `teistro_spike.h`.
pub(crate) fn render(api: &Api) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "/* GENERATED by teistro-spike-a-gen from {}. Do not edit. */\n#ifndef TEISTRO_SPIKE_H\n#define TEISTRO_SPIKE_H\n\n#include <stddef.h>\n#include <stdint.h>\n\n#ifdef __cplusplus\nextern \"C\" {{\n#endif\n\n#define TSP_ABI_VERSION {}u\n",
        api.source, api.abi_version
    );
    for e in &api.enums {
        let _ = writeln!(
            out,
            "{}typedef enum {} {{",
            block_comment(&e.doc, ""),
            e.name
        );
        for v in &e.values {
            let _ = writeln!(
                out,
                "{}    {}_{} = {},",
                block_comment(&v.doc, "    "),
                screaming(&e.name),
                screaming(&v.name),
                v.value
            );
        }
        let _ = writeln!(out, "}} {};\n", e.name);
    }
    for o in &api.opaques {
        let _ = writeln!(
            out,
            "{}typedef struct {} {};\n",
            block_comment(&o.doc, ""),
            o.name,
            o.name
        );
    }
    for c in &api.callbacks {
        let params: Vec<String> = c
            .params
            .iter()
            .map(|p| format!("{} {}", c_type(&p.ty), p.name))
            .collect();
        let _ = writeln!(
            out,
            "{}typedef {} (*{})({});\n",
            block_comment(&c.doc, ""),
            c_type(&c.returns),
            c.name,
            params.join(", ")
        );
    }
    for s in &api.structs {
        let _ = writeln!(
            out,
            "{}typedef struct {} {{",
            block_comment(&s.doc, ""),
            s.name
        );
        for f in &s.fields {
            let _ = writeln!(
                out,
                "{}    {} {};",
                block_comment(&field_doc(f, DocStyle::Prose), "    "),
                c_type(&f.ty),
                f.name
            );
        }
        let _ = writeln!(out, "}} {};\n", s.name);
    }
    for f in &api.functions {
        let params: Vec<String> = f
            .params
            .iter()
            .map(|p| {
                let qualifier = if p.role == Role::VtableIn {
                    "/* nullable */ "
                } else {
                    ""
                };
                format!("{qualifier}{} {}", c_type(&p.ty), p.name)
            })
            .collect();
        let params = if params.is_empty() {
            String::from("void")
        } else {
            params.join(", ")
        };
        let returns = f
            .returns
            .as_ref()
            .map_or_else(|| String::from("void"), c_type);
        let mut doc = f.doc.clone();
        if let Some(safety) = &f.safety {
            let _ = write!(doc, "\nSafety: {safety}");
        }
        let _ = writeln!(
            out,
            "{}{returns} {}({params});\n",
            block_comment(&doc, ""),
            f.name
        );
    }
    out.push_str("#ifdef __cplusplus\n}\n#endif\n\n#endif /* TEISTRO_SPIKE_H */\n");
    out
}

/// The C spelling of a boundary type.
pub(crate) fn c_type(ty: &TypeRef) -> String {
    match ty {
        TypeRef::Scalar { name } => match name.as_str() {
            "u8" => "uint8_t",
            "u16" => "uint16_t",
            "u32" => "uint32_t",
            "u64" => "uint64_t",
            "i8" => "int8_t",
            "i16" => "int16_t",
            "i32" => "int32_t",
            "i64" => "int64_t",
            "f32" => "float",
            "f64" => "double",
            "usize" => "size_t",
            "isize" => "ptrdiff_t",
            "bool" => "bool",
            other => other,
        }
        .to_string(),
        TypeRef::Enum { name }
        | TypeRef::Struct { name }
        | TypeRef::Opaque { name }
        | TypeRef::Callback { name } => name.clone(),
        TypeRef::Pointer { to, mutable } => {
            let inner = c_type(to);
            if *mutable {
                format!("{inner} *")
            } else {
                format!("const {inner} *")
            }
        }
        TypeRef::Void => String::from("void"),
        TypeRef::Char => String::from("char"),
    }
}
